logger = logging.getLogger("desktopenv.metrics.gimp")


def check_brightness_decrease_30_percent(result_path, expected_path):
    """
    Evaluator for task: Decrease the brightness of image by 30%

    This function checks:
    1. The result image brightness is lower than the source image
    2. The brightness decrease is approximately 30%
    3. The image structure/content is preserved

    Args:
        result_path: Result image path (brightness decreased image) - from VM
        expected_path: Source image path (original image) - from cloud

    Returns:
        float: 1.0 if success, 0.0 if failure
    """
    import os
    import logging
    from PIL import Image, ImageStat
    import numpy as np

    logger = logging.getLogger(__name__)

    if result_path is None or expected_path is None:
        logger.warning("Result or expected path is None")
        return 0.0

    if not os.path.exists(result_path) or not os.path.exists(expected_path):
        logger.error(f"File not found: result={result_path}, expected={expected_path}")
        return 0.0

    try:
        # Load images
        source_img = Image.open(expected_path)
        result_img = Image.open(result_path)

        # Convert to grayscale for brightness comparison
        if source_img.mode != 'L':
            source_gray = source_img.convert('L')
        else:
            source_gray = source_img

        if result_img.mode != 'L':
            result_gray = result_img.convert('L')
        else:
            result_gray = result_img

        # Ensure same size
        if source_gray.size != result_gray.size:
            logger.warning(f"Size mismatch: source={source_gray.size}, result={result_gray.size}")
            result_gray = result_gray.resize(source_gray.size, Image.Resampling.LANCZOS)

        source_array = np.array(source_gray)
        result_array = np.array(result_gray)

        # Calculate average brightness
        source_brightness = np.mean(source_array)
        result_brightness = np.mean(result_array)

        logger.info(f"Source brightness: {source_brightness:.2f}, Result brightness: {result_brightness:.2f}")

        # Check 1: Brightness should be decreased
        brightness_decreased = result_brightness < source_brightness

        if not brightness_decreased:
            logger.warning(f"Brightness not decreased: {result_brightness} >= {source_brightness}")
            return 0.0

        # Check 2: Brightness decrease should be approximately 30%
        # Allow tolerance of ±10%
        expected_decrease_ratio = 0.30
        actual_decrease_ratio = (source_brightness - result_brightness) / source_brightness

        brightness_correct = 0.20 <= actual_decrease_ratio <= 0.40
        logger.info(f"Brightness decrease ratio: {actual_decrease_ratio:.2%} (expected: ~{expected_decrease_ratio:.0%})")

        if not brightness_correct:
            logger.warning(f"Brightness decrease ratio out of range: {actual_decrease_ratio:.2%}")
            return 0.0

        # Check 3: Structure should be preserved (correlation check)
        # Flatten arrays
        source_flat = source_array.flatten().astype(float)
        result_flat = result_array.flatten().astype(float)

        # Calculate correlation
        if np.std(source_flat) > 0 and np.std(result_flat) > 0:
            correlation = np.corrcoef(source_flat, result_flat)[0, 1]
            structure_preserved = correlation > 0.8  # High correlation means structure preserved
        else:
            structure_preserved = True

        logger.info(f"Structure correlation: {correlation:.4f}, preserved: {structure_preserved}")

        # Success criteria
        success = (
            brightness_decreased and
            brightness_correct and
            structure_preserved
        )

        result = 1.0 if success else 0.0
        logger.info(f"check_brightness_decrease_30_percent result: {result} " +
                   f"(decreased={brightness_decreased}, correct_ratio={brightness_correct}, " +
                   f"structure_preserved={structure_preserved})")

        return result

    except Exception as e:
        logger.error(f"check_brightness_decrease_30_percent error: {e}")
        return 0.0
